/* CinterForge-owned Code-OSS workbench UI. Current source; no generated copy. */
(function () {
    'use strict';

    var channel = typeof BroadcastChannel === 'function' ? new BroadcastChannel('cinterforge-ifplayer-code-ui') : null;
    var controlChannel = typeof BroadcastChannel === 'function' ? new BroadcastChannel('cinterforge-ifplayer-control') : null;
    if (controlChannel) controlChannel.onmessage = async function (event) {
        if (!event || !event.data || event.data.type !== 'request') return;
        var request = event.data, id = String(request.id || '');
        try {
            var base = String(parent && parent.CINTERFORGE_IF_HOST_BASE || '').replace(/\/$/, '');
            if (!base) throw new Error('CinterForge authoring host is unavailable');
            var options = {method:String(request.method || 'POST'), cache:'no-store', headers:{'Content-Type':'application/json'}};
            if (options.method !== 'GET') options.body = JSON.stringify(request.body || {});
            var response = await fetch(base + String(request.path || ''), options);
            var payload = await response.json().catch(function () { return {}; });
            controlChannel.postMessage({type:'response',id:id,ok:response.ok && payload.ok !== false,payload:payload,error:payload.error || (response.ok ? '' : 'HTTP ' + response.status),error_code:payload.error_code || ''});
        } catch (error) {
            controlChannel.postMessage({type:'response',id:id,ok:false,payload:{},error:String(error && error.message || error),error_code:'local_control_bridge'});
        }
    };
    var terminalNames = [];
    var activeTerminal = '';

    function normalize(value) { return String(value || '').replace(/\s+/g, ' ').trim(); }
    function cleanMenuLabel(value) {
        return normalize(value)
            .replace(/[\t ]+[⇧⌘⌃⌥].*$/, '')
            .replace(/[\t ]+(?:Ctrl|Cmd|Alt|Shift|⌘|⌥|⌃|⇧)[+\-A-Za-z0-9 ].*$/, '')
            .trim();
    }
    function post(type, extra) {
        if (!channel) return;
        var payload = {type: type};
        if (extra) Object.keys(extra).forEach(function (key) { payload[key] = extra[key]; });
        channel.postMessage(payload);
    }

    /* ---------- CinterForge activity-bar logo menu ---------- */
    var cinterForgeMenu = null;
    var cinterForgeMenuButton = null;
    var cinterForgeEntries = [
        ['New Game','game-new',false],
        ['Save Game','game-save',false],
        ['Load Game','game-load',false],
        ['Delete Save','game-delete',false],
        ['Save World','save-world',true],
        ['Sync','sync',false],
        ['Build','build-story',true],
        ['Test','test',false],
        ['Play','play',false],
        ['Pretty Print','pretty-print',true],
        ['Quit','quit',true]
    ];
    var gameMenuRequests = {};
    var nextGameMenuRequest = 1;
    if (channel) channel.addEventListener('message', function (event) {
        var data=event && event.data || {};
        if (data.type !== 'game-menu-response') return;
        var pending=gameMenuRequests[String(data.requestId || '')];
        if (!pending) return;
        delete gameMenuRequests[String(data.requestId || '')];
        if (data.ok) pending.resolve(data.result || {});
        else pending.reject(new Error(String(data.error || 'Game menu action failed')));
    });
    function requestGameMenu(action, saveId) {
        if (!channel) return Promise.reject(new Error('CinterForge game menu bridge is unavailable'));
        var requestId='game-menu-' + nextGameMenuRequest++;
        return new Promise(function (resolve,reject) {
            gameMenuRequests[requestId]={resolve:resolve,reject:reject};
            channel.postMessage({type:'game-menu-request',requestId:requestId,action:action,saveId:String(saveId || '')});
        });
    }
    function saveLabel(save) {
        var label=normalize(save && save.label || 'Saved Game');
        var location=normalize(save && save.location || '');
        return location ? label + ' — ' + location : label;
    }
    async function showGameSaveMenu(button, action) {
        var rect=button.getBoundingClientRect();
        var result=await requestGameMenu('list');
        var saves=Array.isArray(result && result.saves) ? result.saves : [];
        closeCinterForgeMenu();
        var menu=document.createElement('div');
        menu.id='cinterforge-file-menu';
        menu.setAttribute('role','menu');
        menu.setAttribute('aria-label',action === 'load' ? 'Load Game' : 'Delete Save');
        menu.style.left=Math.max(0,rect.right + 4) + 'px';
        menu.style.top=Math.max(0,rect.top) + 'px';
        if (!saves.length) {
            var empty=document.createElement('button');
            empty.type='button'; empty.className='cinterforge-file-menu-item'; empty.disabled=true; empty.textContent='No Saved Games';
            menu.appendChild(empty);
        }
        saves.forEach(function (save) {
            var row=document.createElement('button');
            row.type='button'; row.className='cinterforge-file-menu-item'; row.setAttribute('role','menuitem'); row.textContent=saveLabel(save);
            row.addEventListener('click',async function (event) {
                event.preventDefault(); event.stopPropagation();
                if (action === 'delete' && !window.confirm('Delete "' + saveLabel(save) + '"?')) return;
                closeCinterForgeMenu();
                try { await requestGameMenu(action,String(save.id || '')); }
                catch (error) { window.alert(String(error && error.message || error)); }
            });
            menu.appendChild(row);
        });
        document.body.appendChild(menu); cinterForgeMenu=menu; cinterForgeMenuButton=button;
        var first=menu.querySelector('button:not([disabled])'); if(first) first.focus();
    }
    function closeCinterForgeMenu() {
        if (cinterForgeMenu) { cinterForgeMenu.remove(); cinterForgeMenu = null; }
        if (cinterForgeMenuButton) cinterForgeMenuButton.setAttribute('aria-expanded','false');
        cinterForgeMenuButton = null;
    }
    function openCinterForgeMenu(button) {
        if (cinterForgeMenu && cinterForgeMenuButton === button) { closeCinterForgeMenu(); return; }
        closeCinterForgeMenu();
        var rect = button.getBoundingClientRect();
        var menu = document.createElement('div');
        menu.id = 'cinterforge-file-menu';
        menu.setAttribute('role','menu');
        menu.setAttribute('aria-label','CinterForge');
        if (button.id === 'cinterforge-activity-menu') {
            menu.style.left = Math.max(0, rect.right + 4) + 'px';
            menu.style.top = Math.max(0, rect.top) + 'px';
        } else {
            menu.style.left = Math.max(0, rect.left) + 'px';
            menu.style.top = Math.max(0, rect.bottom) + 'px';
        }
        cinterForgeEntries.forEach(function (entry) {
            var row = document.createElement('button');
            row.type = 'button';
            row.className = 'cinterforge-file-menu-item' + (entry[2] ? ' group-start' : '');
            row.setAttribute('role','menuitem');
            row.textContent = entry[0];
            row.addEventListener('click', async function (event) {
                event.preventDefault(); event.stopPropagation();
                var action=entry[1];
                if (action==='game-load') { await showGameSaveMenu(row,'load'); return; }
                if (action==='game-delete') { await showGameSaveMenu(row,'delete'); return; }
                if (action==='game-new') {
                    if (!window.confirm('Start a New Game? Unsaved game progress will be lost.')) return;
                    closeCinterForgeMenu();
                    try { await requestGameMenu('new'); } catch (error) { window.alert(String(error && error.message || error)); }
                    return;
                }
                if (action==='game-save') {
                    closeCinterForgeMenu();
                    try { await requestGameMenu('save'); } catch (error) { window.alert(String(error && error.message || error)); }
                    return;
                }
                closeCinterForgeMenu();
                post('menu-action',{action:action});
            });
            menu.appendChild(row);
        });
        document.body.appendChild(menu);
        cinterForgeMenu = menu; cinterForgeMenuButton = button;
        button.setAttribute('aria-expanded','true');
        var first = menu.querySelector('button'); if (first) first.focus();
    }
    var cinterForgeLogoData = 'data:image/png;base64,';
    function installCinterForgeMenu() {
        if (document.getElementById('cinterforge-activity-menu')) return;
        var activity = document.querySelector('.part.activitybar .content') || document.querySelector('.part.activitybar');
        if (!activity) return;
        var button = document.createElement('button');
        button.id = 'cinterforge-activity-menu';
        button.type = 'button';
        button.title = 'CinterForge';
        button.setAttribute('aria-label','CinterForge');
        button.setAttribute('aria-haspopup','true');
        button.setAttribute('aria-expanded','false');
        var img = document.createElement('img');
        img.src = cinterForgeLogoData;
        img.alt = '';
        button.appendChild(img);
        button.addEventListener('click', function (event) {
            event.preventDefault(); event.stopImmediatePropagation();
            openCinterForgeMenu(button);
        }, true);
        var compactMenu = activity.querySelector('.menubar.compact,.menubar-menu-button,.menubar');
        if (compactMenu) activity.insertBefore(button, compactMenu);
        else activity.insertBefore(button, activity.firstChild);
    }
    document.addEventListener('pointerdown', function (event) {
        if (cinterForgeMenu && !cinterForgeMenu.contains(event.target) && !cinterForgeMenuButton?.contains?.(event.target)) closeCinterForgeMenu();
    }, true);
    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && cinterForgeMenu) { event.preventDefault(); closeCinterForgeMenu(); return; }
        if (!cinterForgeMenu) return;
        var rows = Array.prototype.slice.call(cinterForgeMenu.querySelectorAll('button'));
        var index = rows.indexOf(document.activeElement);
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
            event.preventDefault();
            var delta = event.key === 'ArrowDown' ? 1 : -1;
            rows[(index + delta + rows.length) % rows.length].focus();
        }
    }, true);

    /* ---------- Panel terminal tabs ---------- */
    function panelBar() { return document.querySelector('.part.panel .composite-bar'); }
    function stockItems() { return Array.prototype.slice.call(document.querySelectorAll('.part.panel .composite-bar .action-item')); }
    function itemText(node) { return normalize(node ? node.textContent : '').toUpperCase(); }
    function isStockTerminal(node) {
        var child = node ? node.querySelector('[aria-label],[title]') : null;
        var meta = normalize([
            node && node.getAttribute('aria-label'), node && node.getAttribute('title'),
            child && child.getAttribute('aria-label'), child && child.getAttribute('title')
        ].join(' ')).toUpperCase();
        return itemText(node) === 'TERMINAL' || meta === 'TERMINAL' || meta.indexOf('TERMINAL ') === 0;
    }
    function terminalButton(name) {
        var button = document.createElement('button');
        button.type = 'button'; button.textContent = name; button.title = name;
        if (name === activeTerminal) button.classList.add('active');
        button.onclick = function () { post('activate-terminal', {name:name}); };
        return button;
    }
    function addTerminalButton() {
        var button = document.createElement('button');
        button.type = 'button'; button.className = 'add'; button.textContent = '+'; button.title = 'New Terminal';
        button.onclick = function () { post('new-terminal'); };
        return button;
    }
    function installTerminalTabs() {
        var bar = panelBar(); if (!bar) return;
        var items = stockItems(), terminal = null, output = null;
        for (var i = 0; i < items.length; i += 1) {
            if (!terminal && isStockTerminal(items[i])) terminal = items[i];
            if (!output && itemText(items[i]) === 'OUTPUT') output = items[i];
        }
        if (terminal) terminal.classList.add('cinterforge-stock-terminal-parent');
        var strip = document.getElementById('cinterforge-terminal-tabs');
        if (!strip) {
            strip = document.createElement('div'); strip.id = 'cinterforge-terminal-tabs';
            if (output && output.parentElement) output.parentElement.insertBefore(strip, output.nextSibling);
            else bar.appendChild(strip);
        }
        var renderKey = JSON.stringify([terminalNames, activeTerminal]);
        if (strip.getAttribute('data-render-key') !== renderKey) {
            while (strip.firstChild) strip.removeChild(strip.firstChild);
            for (var n = 0; n < terminalNames.length; n += 1) strip.appendChild(terminalButton(terminalNames[n]));
            strip.appendChild(addTerminalButton()); strip.setAttribute('data-render-key', renderKey);
        }
        document.body.classList.add('cinterforge-terminal-tabs-ready');
    }

    function bindBuildIcon() {
        var nodes = document.querySelectorAll('[aria-label^="Run and Debug"]');
        for (var i = 0; i < nodes.length; i += 1) {
            var node = nodes[i]; if (node.getAttribute('data-cinterforge-build-bound') === '1') continue;
            node.setAttribute('data-cinterforge-build-bound','1'); node.setAttribute('aria-label','Build Story'); node.setAttribute('title','Build Story');
            node.addEventListener('click', function (event) { event.preventDefault(); event.stopImmediatePropagation(); post('menu-action', {action:'build-story'}); }, true);
        }
    }
    function apply() { installCinterForgeMenu(); bindBuildIcon(); installZMachinePanelTab(); }
    function installZMachinePanelTab() {
        // Server authoring exposes Z-Machine as a peer of PROBLEMS / OUTPUT /
        // TERMINAL while retaining Code's native terminal-instance selector on
        // the right. Local file:// authoring keeps its existing presentation.
        if (window.location.protocol === 'file:') return;
        var bar = panelBar(); if (!bar) return;
        var existing = document.getElementById('cinterforge-zmachine-panel-tab');
        if (existing) return;
        var items = stockItems(), terminal = null;
        for (var i = 0; i < items.length; i += 1) if (!terminal && isStockTerminal(items[i])) terminal = items[i];
        if (!terminal || !terminal.parentElement) return;
        var peer = terminal.cloneNode(true);
        peer.id = 'cinterforge-zmachine-panel-tab';
        peer.removeAttribute('aria-selected');
        var labels = peer.querySelectorAll('[aria-label],[title]');
        for (var j = 0; j < labels.length; j += 1) { labels[j].setAttribute('aria-label','Z-Machine'); labels[j].setAttribute('title','Z-Machine'); }
        var textNodes = peer.querySelectorAll('.action-label');
        if (textNodes.length) textNodes[0].textContent = 'Z-MACHINE';
        else peer.textContent = 'Z-MACHINE';
        peer.addEventListener('click', function (event) {
            event.preventDefault(); event.stopImmediatePropagation();
            post('activate-terminal', {name:'Z-Machine'});
        }, true);
        terminal.parentElement.insertBefore(peer, terminal);
    }
    if (channel) channel.onmessage = function (event) {
        if (!event || !event.data || event.data.type !== 'terminal-tabs') return;
        installZMachinePanelTab();
        return; // Native Code terminal instance tabs remain authoritative.
        var incoming = Array.isArray(event.data.names) ? event.data.names : [], filtered = [];
        for (var i = 0; i < incoming.length; i += 1) {
            var name = String(incoming[i] || ''); if (name === 'Z-Machine' || /^Terminal \d+$/.test(name)) filtered.push(name);
        }
        terminalNames = filtered.length ? filtered : ['Z-Machine','Terminal 1'];
        terminalNames.sort(function (a,b) { if (a === 'Z-Machine') return -1; if (b === 'Z-Machine') return 1; return Number((a.match(/\d+/)||['0'])[0])-Number((b.match(/\d+/)||['0'])[0]); });
        activeTerminal = String(event.data.active || ''); installTerminalTabs();
    };
    // Do not observe the entire Code workbench DOM. VS Code mutates it continuously
    // during layout/editor/terminal activity; invoking apply() for every childList
    // mutation can monopolize the browser main thread and make the embedded server
    // workbench appear completely frozen. File-menu shaping is already event-driven,
    // terminal tabs are refreshed by their BroadcastChannel, and a bounded startup
    // sequence is sufficient for the persistent activity-bar affordance.
    document.addEventListener('DOMContentLoaded',apply,{once:true});
    [0, 100, 300, 750, 1500, 3000].forEach(function (delay) { setTimeout(apply,delay); });
    window.addEventListener('load',apply,{once:true});
    console.info('[CinterForge Code UI] workbench customization loaded current-source-v5');
}());
